          if (on > 0) { const jy = (H1(j * 31 + q * 7) - .5) * 4, ja = .82 + .18 * H1(j * 13 + q * 3); tx(c, w[q], cx, y + jy, { ...o2, a: on * ja, c: C.ink }) }
