      c.save(); c.translate(V1.x, V1.y + (1 - k) * 980); c.rotate(V1.r + (1 - k) * .35); c.scale(V1.s, V1.s);
      vapeBody(c, { ...HERO, t, led: led0, mk: 1, wk: 1, lk: at(t, K.morphE - .3, K.morphE), bub: 1 - at(t, K.liq, K.liq + .25) });
      c.restore(); return;
