    for (let i = 0; i < 26; i++) { const x = H1(i * 7.3) * 2100 - 90, y = ((H1(i * 3.1) * 1300 - t * (14 + 22 * H1(i))) % 1300 + 1300) % 1300 - 110, r = 6 + 16 * H1(i * 1.7); c.globalAlpha = (.14 + .1 * H1(i)) * .4; c.beginPath(); c.arc(x, y, r, 0, TAU); c.stroke() }
