      const fo = ei(at(t, K.liq - .35, K.liq + .3)), FO = (x, y, f = 1) => { const dx = x - V1.x, dy = y - V1.y + 60, L = Math.hypot(dx, dy) || 1; return [x + dx / L * 1500 * fo * f, y + dy / L * 1500 * fo * f] };
