      { const [x, y] = FO(640, 330); mangoSlice(c, x, y + Math.sin(t * 1.9 + 2) * 8, spr(at(t, K.mango + .12, K.mango + .57)) * .78, .3 + .04 * Math.sin(t * 1.6) + fo * 1.2) }
      { const [x, y] = FO(400, 480); mangoSlice(c, x, y + Math.sin(t * 1.7) * 8, spr(at(t, K.mango + .22, K.mango + .67)) * .62, -.5 + .05 * Math.sin(t * 1.4) - fo) }
      const kn = spr(at(t, K.mint, K.mint + .45));
      { const [x, y] = FO(1330, 310); mintLeaf(c, x, y + Math.sin(t * 2 + 1) * 8, kn * .78, -.55 + .06 * Math.sin(t * 1.9 + 1) + fo) }
      { const [x, y] = FO(1350, 650); mintLeaf(c, x, y + Math.sin(t * 2.3) * 8, spr(at(t, K.mint + .12, K.mint + .57)) * .66, .45 + .05 * Math.sin(t * 1.5) - fo) }
      { const [x, y] = FO(1560, 520); iceCube(c, x, y + Math.sin(t * 2.1 + 3) * 7, spr(at(t, K.mint + .25, K.mint + .65)) * .62, .2 + .05 * Math.sin(t * 1.3) + fo * 2) }
      { const [x, y] = FO(1690, 430); iceCube(c, x, y + Math.sin(t * 1.8 + 1) * 7, spr(at(t, K.mint + .35, K.mint + .75)) * .5, -.25 + .05 * Math.sin(t * 1.6) - fo * 2) }
      heroVape(c, t);
