    c.strokeStyle = 'rgba(232,240,255,.3)'; c.lineWidth = 15;
    for (const sx of [-1, 1]) { c.beginPath(); c.moveTo(sx * 40, -150); c.bezierCurveTo(sx * 110, -172, sx * 172, -118, sx * 268, -152); c.stroke() }
