      const draw = (P, w) => { for (const [ww, a] of [[1, .3], [.68, .42], [.36, .7]]) { c.save(); c.globalAlpha *= a; c.strokeStyle = fcol; c.lineWidth = w * ww * sq2; c.lineCap = 'round'; c.lineJoin = 'round'; c.beginPath(); P.forEach(([x, y], i) => i ? c.lineTo(x, y) : c.moveTo(x, y)); c.stroke(); c.restore() } };
      draw(T, 60); if (br > 0) { draw(B(-1), 44); draw(B(1), 44) }
