    for (let x = 2040; x <= 4840; x += 80) { c.moveTo(x, -300); c.lineTo(x, 790) } for (let y = -300; y <= 790; y += 80) { c.moveTo(2040, y); c.lineTo(4840, y) } c.stroke(); c.restore();
