      const lv = 60 + 40 * H1(i * 3.7); rr(c, x - 12, -24 - lv, 24, lv, [2, 2, 12, 12]); fill(c, cols[i]);
      for (let j = 0; j < 2; j++) { const ph = (t * (.5 + .3 * H1(i + j * 5)) + H1(i * 7 + j)) % 1; circ(c, x - 4 + 8 * j, lp(-30, -20 - lv, ph), 3.5, 'rgba(255,255,255,.7)') }
