    c.fillStyle = '#5a2e12'; c.fillRect(360, 760, 1200, 40); c.fillStyle = '#4a2410'; c.fillRect(340, 796, 1240, 40);   // ступени возвышения
    c.fillStyle = '#6b3a1a'; c.fillRect(400, 560, 1120, 220); c.fillStyle = '#8a4a1c'; c.fillRect(380, 540, 1160, 36);
    for (let i = 0; i < 4; i++) { rr(c, 450 + i * 262, 600, 222, 150, 10); stroke(c, '#4a2410', 8) }
    c.fillStyle = '#5c2e0e'; c.fillRect(1600, 610, 230, 190); c.fillStyle = '#7a3f15'; c.fillRect(1590, 596, 250, 24); rr(c, 1630, 640, 170, 120, 8); stroke(c, '#3b1c07', 6);   // место свидетеля
    c.strokeStyle = '#1b1b1b'; c.lineWidth = 5; c.beginPath(); c.moveTo(1715, 596); c.lineTo(1700, 540); c.stroke(); circ(c, 1698, 532, 10, '#222');
    c.beginPath(); c.ellipse(SBc.x, SBc.y - 4, 110, 26, 0, 0, TAU); fill(c, C.wood); c.fillStyle = C.wood; c.fillRect(SBc.x - 110, SBc.y - 30, 220, 26); c.fillStyle = C.gold; c.fillRect(SBc.x - 110, SBc.y - 20, 220, 8); c.beginPath(); c.ellipse(SBc.x, SBc.y - 30, 110, 26, 0, 0, TAU); fill(c, C.wood3);
    // v16.3 (Gemini): молоток не висит в воздухе — лежит на подставке (голова на подставке, рукоять на столе) и подпрыгивает от удара
    const hop = tt0 => { const u = at(t, tt0 - .16, tt0 + .12); return u <= 0 || u >= 1 ? 0 : u < .55 ? eo(u / .55) : 1 - ei((u - .55) / .45) };
