  // v16.3 (Андрей: «верх как у настоящей»): башня Гувера — светлый ствол с нишами, наверху смотровая площадка с арочными проёмами,
  // над ней красный купол с фонарём; внизу — аркада университета (часов у настоящей башни нет)
