    c.strokeStyle = 'rgba(190,250,226,.26)'; c.lineWidth = 3; c.beginPath(); for (let x = 0; x <= WW; x += 200) { c.moveTo(x, -200); c.lineTo(x, HH + 200) } for (let y = 0; y <= HH; y += 200) { c.moveTo(-200, y); c.lineTo(WW + 200, y) } c.stroke();
