    c.fillStyle = '#56607a'; for (let i = 0; i <= 176; i++) c.fillRect(-870 + i * 10, -30, 2, i % 10 ? (i % 5 ? 10 : 16) : 22);
    for (let i = 0; i <= 17; i++) tx(c, String(i), -870 + i * 100, 14, { f: 'J', w: 700, s: 15, c: '#56607a' });
    c.restore();
    circ(c, 170, 772, 104, 'rgba(0,0,0,.22)'); circ(c, 160, 760, 104, '#e9e4dc'); circ(c, 160, 760, 80, '#3a2416'); c.beginPath(); c.arc(160, 760, 64, 0, TAU); stroke(c, 'rgba(255,230,190,.35)', 6);   // v16.3: кружка ниже — метка «2015» на неё не налезает
