  // карточки глав фильма (план Андрея, пульт v16.3): 1 вейпы — «1979 · СОЛЬ», 2 Китай и ледяной вкус — «2020 · ЛАЗЕЙКА ОДНОРАЗОК»,
  // 3 «Мальборо» — 1924, 4 нагреватели — 2014, 5 шайбы — 2022 (покупка Swedish Match). Фото на карточке — 16:9 (кадр главы ложится в него без шва)
