    Q(K.court - .25, 'whoosh', .55); Q(K.tob, 'thud', .8); Q(K.secrets - .08, 'impact', .55); Q(K.secrets - .05, 'vaultopen', .9); Q(K.secrets + .12, 'papers', 1); Q(K.pub + .2, 'papers', .55); Q(K.bzoom, 'deep', .45);
