    let bx = 646; for (let i = 0; i < 9; i++) { const w = 22 + 12 * H1(i * 3.3), h = 92 + 50 * H1(i * 7.1); if (i === 6) { c.save(); c.translate(bx + 4, 440); c.rotate(-.2); c.fillStyle = mixc(BK[i], '#1c2350', .35); c.fillRect(0, -h, w, h); c.restore(); bx += w + 18; continue } c.fillStyle = mixc(BK[i], '#1c2350', .35); c.fillRect(bx, 440 - h, w, h); c.fillStyle = 'rgba(255,255,255,.18)'; c.fillRect(bx + 3, 440 - h + 14, w - 6, 4); bx += w + 3 }
    rr(c, 930, 398, 56, 42, [4, 4, 14, 14]); fill(c, '#7a4f22'); for (const [lx, ly, r] of [[958, 360, -.5], [944, 372, -1.2], [972, 370, .6], [958, 380, -2.6]]) leafV(c, lx, ly, r);
    // стол
    c.fillStyle = '#4a2e1c'; c.fillRect(-400, 936, WW + 800, 70); c.fillStyle = '#6b4128'; c.fillRect(-400, 932, WW + 800, 8); c.fillStyle = '#2a1a10'; c.fillRect(-400, 1006, WW + 800, 900);
    // кружка и распечатки «тех самых бумаг»
