  // штамп «ТОЛЬКО НА YOUTUBE» по центру на «YouTube», «?» и «!» в свободном месте; вжух — ровно в кадр 0 ----------
  const BCV = [
    { x: 290, y: 430, r: -.035, yr: '1979', cap: 'СОЛЬ' }, { x: 790, y: 405, r: .03, yr: '2020', cap: 'ЛАЗЕЙКА ОДНОРАЗОК' },
    { x: 540, y: 770, r: -.02, yr: '1924', cap: '«МАЛЬБОРО»' }, { x: 285, y: 1110, r: .035, yr: '2014', cap: 'НАГРЕВАТЕЛИ' }, { x: 795, y: 1100, r: -.02, yr: '2022', cap: 'ШАЙБЫ' },
  ];
